-- Translators: Claude (AI-assisted, not yet reviewed by a native speaker), Codex (AI-assisted, not yet reviewed by a native speaker)
-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "神聖"
L["rm.era.paladin.holy.Description"] = "神聖天賦樹在隊伍中的治療，從 10 級起。作用於你的友方目標，並依損失的生命力選擇治療法術：清潔術或純淨術，移動時使用神聖震擊，低於 40% 時使用最高等級的聖光術，低於 65% 時使用等級 6 的聖光術，低於 85% 時使用最高等級的聖光閃現，低於 95% 時使用等級 4 的聖光閃現。敵人位於近戰範圍內時：智慧聖印，以及團隊以外的審判。提醒：專注光環或虔誠光環、智慧祝福、對生命力極低的目標使用神恩術與聖療術。要治療誰由你決定；單人練功的神聖聖騎士會使用懲戒內建循環。"
L["rm.era.paladin.protection.Name"] = "防護"
L["rm.era.paladin.protection.Description"] = "1 至 60 級的坦克，開啟正義之怒或使用防護天賦樹時選用。以正義聖印（法力低於 40% 時用智慧聖印）、神聖之盾與審判拉怪，維持神聖之盾，兩個以上敵人與你交戰時使用奉獻與神聖憤怒（不死族與惡魔），否則施放一次十字軍審判，然後在法力有餘時使用審判與奉獻，對不死族與惡魔使用驅邪術。提醒：正義之怒、虔誠光環、庇護祝福、王者祝福或力量祝福、瀕死時使用聖療術。嘲諷、連續施放王者祝福與法術等級由你自行處理。"
L["rm.era.paladin.protection.icyveins.Name"] = "防護，智慧聖印（Icy Veins）"
L["rm.era.paladin.protection.icyveins.Description"] = "Icy Veins 的團隊坦克搭配 Wowhead 的智慧循環，作為推薦的防護內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。維持智慧聖印，目標身上沒有智慧審判時就審判，否則只在拉怪時審判；神聖之盾、奉獻冷卻結束即使用、對不死族與惡魔怪群使用神聖憤怒、驅邪術，並在團隊中以強效王者祝福作為威脅值填充。提醒與推薦的內建循環相同。"
L["rm.era.paladin.retribution.Name"] = "懲戒"
L["rm.era.paladin.retribution.Description"] = "懲戒近戰，適用於 1 至 60 級，也是沒有其他內建循環適用時所有聖騎士的預設循環。在團隊以外對精英與長時間戰鬥施放十字軍聖印並審判一次；否則維持一個聖印（武器速度 3.5 秒或更慢時用命令聖印，否則用正義聖印），對不死族與惡魔使用驅邪術與神聖憤怒，憤怒之錘，審判冷卻結束即使用，復仇生效時或附近有兩個以上敵人時使用奉獻。提醒：聖潔光環、懲戒光環或虔誠光環、單人時智慧祝福或隊伍中力量祝福、戰鬥之間治療、即將死亡時使用聖盾術、聖佑術或聖療術。聖印輪替是另一個內建循環；目標選擇與站位由你自行處理。"
L["rm.era.paladin.retribution.twist.Name"] = "懲戒，聖印輪替"
L["rm.era.paladin.retribution.twist.Description"] = "預設關閉；如果你會輪替聖印，請啟用它。適用於擁有命令聖印的懲戒聖騎士：維持正義聖印，在揮擊前的最後 0.4 秒切換為等級 1 的命令聖印，然後再換回來，審判一就緒就使用，對不死族與惡魔使用驅邪術與神聖憤怒，憤怒之錘，復仇生效時使用奉獻。需要大量法力與良好的時機掌握。提醒與懲戒內建循環相同。"
L["rm.forever.paladin.holy.Name"] = "神聖"
L["rm.forever.paladin.holy.Description"] = "當神聖是你的主要天賦樹且已投入 21 點（神聖震擊所在層）、正義之怒未開啟時的隊伍治療（隊伍中的震擊騎也會使用這裡）。治療你目前的友方目標：對帶有你的聖光戒備的目標使用神聖震擊，戰鬥中使用聖光戒備，清潔術或純淨術，移動時使用神聖震擊，聖光灌注時使用聖光術，聖光閃現作為主要治療。目標為敵人時：有光明聖印時使用聖光審判，神聖震擊、聖光戒備、神聖打擊、驅邪術。提醒：沒有聖印時使用光明聖印、戰鬥中對友方目標使用神恩術、你的光環與祝福。在永久版本中，插件看不到生命力與法力，因此你選取的目標是判斷誰需要治療的唯一依據；緊急神聖震擊、大量聖光術與聖療術由你決定。"
L["rm.forever.paladin.holy.wowhead.Name"] = "神聖，神聖震擊冷卻結束即使用（Wowhead）"
L["rm.forever.paladin.holy.wowhead.Description"] = "Wowhead 的治療打法，作為推薦的神聖內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。神聖震擊作為常規治療冷卻結束即使用、驅散、聖光閃現（永久版本會隱藏生命力，因此損失較多時使用聖光術由你決定）。目標為敵人時，它會透過切換到光明聖印、審判，再切換回正義聖印來維持你的聖光審判，然後是神聖打擊、對不死族與惡魔使用驅邪術、神聖震擊與奉獻。提醒與神聖內建循環相同。"
L["rm.forever.paladin.protection.Name"] = "防護（Wowhead）"
L["rm.forever.paladin.protection.Description"] = "當防護是你的主要天賦樹，或你開啟正義之怒後的坦克循環。目標正在攻擊其他人時：搭配憤怒聖印使用審判（嘲諷），以迅捷審判重置它。與兩個以上敵人交戰時：奉獻、對不死族與惡魔使用驅邪術與神聖憤怒、神聖打擊。單一敵人時：對不死族與惡魔使用驅邪術、神聖打擊、奉獻。提醒：正義之怒、憤怒聖印、審判冷卻結束即使用、坦克時的神聖之盾、你的光環與祝福。在永久版本中，插件看不到生命力與法力，因此聖殿騎士之壁壘與聖療術由你決定。拉怪、站位與其他嘲諷由你自行處理。"
L["rm.forever.paladin.protection.icyveins.Name"] = "防護，奉獻優先（Icy Veins）"
L["rm.forever.paladin.protection.icyveins.Description"] = "Icy Veins 的坦克打法，作為推薦的 Wowhead 防護內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。只要負擔得起就優先奉獻，單一敵人時也一樣；審判留作嘲諷使用（沒有冷卻結束即使用的提醒），以迅捷審判重置它；然後是神聖打擊，對不死族與惡魔使用驅邪術。其餘坦克提醒相同。"
L["rm.forever.paladin.retribution.Name"] = "懲戒"
L["rm.forever.paladin.retribution.Description"] = "適用於 1 至 60 級的懲戒及所有近戰聖騎士，也是永久聖騎士的預設循環。維持一個傷害聖印，只在即將消失時刷新：對精英目標審判一次十字軍聖印，接著使用慢速（3.0 秒）武器時用命令聖印，否則用正義聖印。然後神聖打擊冷卻結束即使用，震擊騎（Shockadin）使用神聖震擊與聖光戒備，對不死族與惡魔使用驅邪術，三個以上敵人時使用奉獻，可施放時使用憤怒之錘，以及近戰。審判不受共用冷卻影響，因此只要有聖印，它就會以提醒出現。其他提醒：你的光環與祝福（學會後為懲戒光環與王者祝福；會保留你自己選擇的）。預設關閉的選擇性步驟：命令聖印審判前使用制裁之錘。在永久版本中，插件看不到法力、生命力與揮擊計時，因此節省法力、治療自己、聖療術與聖光折射聖印切換都由你決定。依據 30 級測試版指南製作。"
L["rm.mop.paladin.holy.Name"] = "推薦"
L["rm.mop.paladin.holy.Description"] = "適用於神聖，從 10 級起在神聖專精下選用。選取友方時進行治療：3 點聖能（或神聖意圖）時，若你附近有三人受傷就使用黎明曙光，否則對沒有永恆之火的目標施放永恆之火，再否則使用榮耀聖言；神聖震擊冷卻結束即使用；聖光灌注用於神聖光輝或神聖之光，三層無私治療者用於神聖光輝或聖光閃現；低於 35% 時使用聖光閃現；隊伍受傷時使用神聖光輝；神聖之光，然後以聖光術補滿。選取敵人時造成傷害：神聖震擊、審判、十字軍聖擊、神聖稜石、死刑宣判、憤怒之錘、問罪。提醒：其他聖印（正義聖印除外）生效中或沒有聖印時使用洞悉聖印、祝福、責難、對你的專注目標施放聖光信標與崇聖護盾（請將坦克設為專注目標）、法力低於 60% 時使用神性祈求、三人低於 70% 時使用聖光之錘與你的治療冷卻技能、對瀕死目標使用聖療術。要治療誰、驅散與滑鼠指向治療由你自行處理。"
L["rm.mop.paladin.protection.Name"] = "推薦"
L["rm.mop.paladin.protection.Description"] = "推薦防護使用，從 10 級起在防護專精下選用。以復仇之盾拉怪，接著大十字軍觸發時使用復仇之盾、復仇之盾、憤怒之錘、十字軍聖擊、審判、你的 90 級天賦、奉獻、神聖憤怒與崇聖護盾。三個以上敵人與你交戰時改用復仇之盾、奉獻、公正之錘、審判與神聖憤怒。公正之盾、永恆之火與榮耀聖言不受共用冷卻影響，因此會在循環旁亮起：負擔得起時就使用公正之盾，3 點聖能且有三層榮耀壁壘時，在你自己的永恆之火即將結束時對自己施放，沒有該天賦時在生命力低於一半時使用榮耀聖言。其他提醒：正義之怒、其他聖印（正義聖印除外）生效中或沒有聖印時使用洞悉聖印、祝福、責難、崇聖護盾、坦怪時使用復仇之怒與神聖復仇者，以及依你的生命力使用遠古諸王守護者、忠誠防衛者、聖佑術與聖療術。它無法看到即將承受的傷害，因此大型防禦技能請自行規劃。"
L["rm.mop.paladin.protection.simulator.Name"] = "蓄積聖能（模擬器）"
L["rm.mop.paladin.protection.simulator.Description"] = "推薦防護內建循環的替代方案，預設關閉：啟用它並停用推薦的循環，或提高它的優先順序。依照模擬器的坦克清單：公正之盾會等到聖能全滿，除非你的生命力低於 40% 或神聖意圖使它免費；有兩層以上榮耀壁壘時，在永恆之火即將消失前施放；維持崇聖護盾；神聖復仇者與復仇之怒冷卻結束即使用。產生聖能的技能依序為十字軍聖擊、審判，然後是復仇之盾、神聖憤怒、90 級天賦與憤怒之錘，三個敵人時的範圍傷害順序相同。配合首領時機的防禦技能由你負責。"
L["rm.mop.paladin.retribution.Name"] = "推薦"
L["rm.mop.paladin.retribution.Description"] = "推薦懲戒使用，從 10 級起在懲戒專精下選用。維持異端審問（3 點聖能時施放，在最後 3 秒內刷新；81 級起），聖能全滿或有免費觸發時先使用聖殿騎士之裁決再產生更多聖能，接著是憤怒之錘、十字軍聖擊、審判與驅邪術，其他技能都未就緒時在 3 點聖能使用聖殿騎士之裁決。復仇之怒期間會立即消耗聖能，並將審判排在十字軍聖擊之前。兩個以上敵人與你交戰時改用神性風暴，四個敵人在近處時加上公正之錘。從遠處以審判或驅邪術拉怪，並在你單人且陷入危險時建議榮耀聖言。提醒：其他聖印生效中或沒有聖印時施放真理聖印（會保留正義聖印）、王者祝福或力量祝福、責難、對精英在異端審問生效時使用復仇之怒與遠古諸王守護者、復仇之怒期間使用神聖復仇者、死刑宣判與聖光之錘，以及生命力低時使用聖佑術與聖療術。用於怪群的正義聖印與雕紋選擇由你自行處理。"
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "驅邪術優先（Warcraft Tavern）"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "推薦懲戒內建循環的替代方案，預設關閉：啟用它並停用推薦的循環，或提高它的優先順序。每次冷卻結束及戰爭藝術重置時優先使用驅邪術；異端審問不在時以任何聖能施放，並在最後 20 秒內以 3 點聖能刷新；然後是十字軍聖擊、審判、聖殿騎士之裁決與憤怒之錘（有聖化之怒時於復仇之怒期間優先使用）。兩個以上敵人時使用十字軍聖擊、聖光之錘、審判、神性風暴與憤怒之錘。只對精英建議復仇之怒與遠古諸王守護者。指南中只要有順劈就使用正義聖印的做法交由你處理。"
L["rm.mop.paladin.unspecialized.Name"] = "選擇專精前"
L["rm.mop.paladin.unspecialized.Description"] = "適用於 1 至 9 級，以及尚未選擇專精的任何聖騎士；選擇專精後由該專精的內建循環接手。從遠處以審判拉怪，接著是十字軍聖擊與審判，單人且生命力低於一半時使用制裁之錘，低於 40% 時使用榮耀聖言。提醒：你不在命令聖印（24 級起為真理聖印）中時施放它、王者祝福、責難，以及戰鬥外受傷時使用聖光閃現。"
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "至暗之夜的神聖專精，僅供參考：Rotation Master 選擇的是法術而不是目標，而且遊戲在戰鬥中會隱藏所有人的生命力，因此它會針對你目前的目標讓聖能與冷卻技能持續運轉，決定誰需要治療則交給你。聖能在戰鬥中仍然可見，因此會先在 5 點時消耗，並在其他治療之後於 3 點以上時消耗。友方目標：聖能達到 5 點時使用永恆之火或榮耀聖言，聖光灌注觸發時使用聖光閃現，神聖震擊，3 點以上時使用永恆之火或榮耀聖言，聖光術，聖光閃現；黎明曙光由你自行處理。敵人：聖能達到 5 點時使用公正之盾，神聖震擊，3 點以上時使用公正之盾，審判，十字軍聖擊，奉獻。戰鬥中的提醒：神聖鳴響、神聖稜石、神聖堅盾或神聖武器、對友方目標使用美德信標、聖佑術；兩波拉怪之間的光環；責難。聖療術由你自行處理。復仇之怒與精通光環由你自行處理。"
L["rm.retail.paladin.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.paladin.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是聖騎士的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個聖騎士內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.paladin.protection.Name"] = "暴雪戰鬥助手"
L["rm.retail.paladin.protection.Description"] = "推薦至暗之夜的防護專精使用。顯示暴雪的戰鬥助手建議（已包含公正之盾、復仇之怒與哨兵），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：兩波拉怪之間的光環、對可中斷的施法使用責難，以及戰鬥中只要就緒就使用忠誠防衛者與遠古諸王守護者。正式版中生命力是隱藏的，因此何時使用它們以及聖療術由你決定。嘲諷與站位由你自行處理。"
L["rm.retail.paladin.protection.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.paladin.protection.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序需要奉獻、守禦先鋒與聖光籠罩的增益效果，而至暗之夜會在戰鬥中隱藏它們。拉怪前使用奉獻；接著是神聖鳴響，聖光之錘，沒有站在奉獻中時使用奉獻，有守禦先鋒時使用復仇之盾，聖能達到 3 點以上時使用公正之盾，憤怒之錘，審判，祝福之錘或公正之錘，復仇之盾，有聖光籠罩時使用榮耀聖言，奉獻。提醒：復仇之怒或哨兵、神聖堅盾、復仇之怒以外使用神聖武器、防禦技能、光環、責難。"
L["rm.retail.paladin.protection.wowhead.Name"] = "奉獻填充參考（Wowhead）"
L["rm.retail.paladin.protection.wowhead.Description"] = "僅供參考，預設關閉：Wowhead 的坦克施放順序。審判冷卻結束就使用，公正之盾，復仇之盾，聖能為 0 時使用神聖鳴響，祝福之錘或公正之錘，奉獻只作為填充。正式版中生命力是隱藏的，因此生命力低於一半時的榮耀聖言由你自行處理。提醒與 Icy Veins 參考循環相同。"
L["rm.retail.paladin.retribution.Name"] = "暴雪戰鬥助手"
L["rm.retail.paladin.retribution.Description"] = "推薦至暗之夜的懲戒專精使用。在戰鬥中，遊戲現在會對插件隱藏增益效果、減益效果、冷卻時間與生命力，因此它會在你的快捷列上顯示暴雪自己的戰鬥助手建議（一鍵循環），並在你施法或沒有選取敵人時停止。它還會提醒你那些建議從不涵蓋的內容：兩波拉怪之間的光環、對可中斷的施法使用責難，以及戰鬥中只要就緒就使用聖佑術。正式版中生命力是隱藏的，因此何時使用聖佑術與聖療術由你決定。飾品與種族技能由你自行處理。"
L["rm.retail.paladin.retribution.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.paladin.retribution.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序需要讀取增益效果、充能與敵人數量，而至暗之夜會在戰鬥中隱藏這些資訊，因此它無法在戰鬥中可靠地運作。聖光之錘；神聖意圖觸發的免費聖能消耗技能；灰燼甦醒冷卻中且聖能達到 5 點時使用聖能消耗技能；灰燼甦醒；神聖鳴響；戰爭藝術觸發時使用正義之刃；憤怒之錘充能溢出前使用憤怒之錘；聖能達到 3 點以上時，兩個以上敵人（或有蒼穹能量）時使用神性風暴，否則使用最終裁決；憤怒之錘；正義之刃；審判；聖殿騎士打擊或十字軍聖擊。聖能在戰鬥中仍然可見，因此這些消耗聖能的時機在戰鬥中可以運作。提醒：復仇之怒、灰燼甦醒就緒時使用死刑宣判、光環、責難、防禦技能。"
L["rm.sod.paladin.holy.Name"] = "神聖（探索賽季）"
L["rm.sod.paladin.holy.Description"] = "探索賽季的隊伍治療，已紋刻聖光信標、神聖之光或崇聖護盾，或使用神聖天賦樹且沒有十字軍聖擊時選用。作用於你的友方目標：清潔術，移動時或低於 30% 時使用神聖震擊，低於 60% 時使用神聖之光（法力低於一半時用聖光術），低於 90% 時使用聖光閃現。敵人位於近戰範圍內時只維持聖印。提醒：對缺少聖光信標與崇聖護盾的目標施放它們、專注光環或虔誠光環、智慧祝福、對生命力極低的目標使用神恩術與聖療術。其依據的指南來自第 4 階段；要治療誰由你決定。"
L["rm.sod.paladin.holy.wowhead.Name"] = "神聖，聖光術優先（探索賽季，Wowhead）"
L["rm.sod.paladin.holy.wowhead.Description"] = "Wowhead 第 4 階段針對高暴擊裝備的治療順序，作為推薦的探索賽季神聖內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。低於 75% 時使用神聖之光或聖光術，然後是清潔術，損失少量生命力或移動時使用神聖震擊，低於 95% 時使用聖光閃現。提醒與推薦的內建循環相同。"
L["rm.sod.paladin.protection.Name"] = "防護（探索賽季）"
L["rm.sod.paladin.protection.Description"] = "探索賽季的坦克，開啟正義之怒、已紋刻公正之錘或公正之盾，或使用防護天賦樹時選用。殉難聖印，以神聖之盾、復仇之盾與驅邪術拉怪，維持神聖之盾；單一目標時：公正之錘、公正之盾、驅邪術、復仇之盾、審判、神性風暴、奉獻；三個以上敵人與你交戰時：公正之錘、復仇之盾、奉獻、公正之盾、驅邪術。提醒：正義之怒、拉怪前的神聖之盾、虔誠光環、庇護祝福或王者祝福、復仇之怒、低於 40% 時使用聖佑術、聖療術、隊伍中你的目標攻擊其他人時使用清算聖禦。"
L["rm.sod.paladin.protection.simulator.Name"] = "防護（探索賽季，模擬器）"
L["rm.sod.paladin.protection.simulator.Description"] = "模擬器 的坦克清單，作為推薦的探索賽季防護內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。有聖印時就審判，在聖印即將結束前更新，神聖之盾、復仇之盾、公正之錘、驅邪術，最後是公正之盾。提醒與推薦的內建循環相同。"
L["rm.sod.paladin.retribution.Name"] = "懲戒（探索賽季）"
L["rm.sod.paladin.retribution.Description"] = "探索賽季的近戰，適用於 1 至 60 級，也是探索賽季中所有聖騎士的預設循環。維持殉難聖印（學會前用正義聖印），以驅邪術開場，三點聖能時施放神性風暴，然後依武器速度決定：使用 3.3 秒或更慢的雙手武器時，十字軍聖擊、驅邪術、神性風暴與審判；使用較快的武器時，只在聖印即將結束時審判，然後是驅邪術、十字軍聖擊與神性風暴。法力充足或附近有三個敵人時使用奉獻，對不死族與惡魔使用神聖憤怒（紋刻淨化之力後對任何敵人皆可），法力有餘時使用憤怒之錘（紋刻強化憤怒之錘後則一律使用）。符文會在你紋刻後納入使用。提醒：聖潔光環、一個祝福、搭配精通光環使用復仇之怒、戰鬥之間治療、即將死亡時使用聖盾術。"
L["rm.sod.paladin.retribution.icyveins.Name"] = "懲戒（探索賽季，Icy Veins 第 4 階段）"
L["rm.sod.paladin.retribution.icyveins.Description"] = "Icy Veins 與 Warcraft Tavern 較舊的第 4 階段清單，也適合升級時使用，是推薦的探索賽季懲戒內建循環的替代方案，預設關閉：啟用它並停用推薦的循環，或提高它的優先順序。對精英與長時間戰鬥施放一次十字軍審判，殉難聖印，驅邪術、十字軍聖擊、神性風暴與審判冷卻結束即使用，法力充足或附近有三個敵人時使用奉獻，憤怒之錘。提醒與推薦的循環相同。"
L["rm.sod.paladin.retribution.stacking.Name"] = "懲戒，聖印疊加（探索賽季）"
L["rm.sod.paladin.retribution.stacking.Description"] = "預設關閉；如果你有守秘者之魂符文或讓聖印延續的六件套裝，請啟用它（Rotation Master 無法看到這兩者）。同時維持命令聖印與殉難聖印，三點聖能時使用神性風暴、十字軍聖擊、驅邪術、對不死族與惡魔使用神聖憤怒（紋刻淨化之力後對任何敵人皆可）、奉獻，並在兩個聖印都存在時審判。"
L["rm.sod.paladin.retribution.twist.Name"] = "懲戒，聖印輪替（探索賽季）"
L["rm.sod.paladin.retribution.twist.Description"] = "預設關閉；如果你會用慢速雙手武器輪替聖印，請啟用它。在每次揮擊前的最後 0.4 秒於殉難聖印與命令聖印之間切換，揮擊前 1.9 秒內不建議任何會觸發共用冷卻的技能，兩個聖印同時存在時審判，每次揮擊使用一個填充技能：三點聖能時使用神性風暴、十字軍聖擊、驅邪術。需要攻擊計時器與練習。"
L["rm.sod.paladin.shockadin.Name"] = "震擊聖騎（探索賽季，模擬器）"
L["rm.sod.paladin.shockadin.Description"] = "預設關閉；如果你用神聖天賦樹造成傷害，請啟用它。它在以神聖作為主要天賦樹且已紋刻震驚與敬畏時適用。殉難聖印（否則用正義聖印），在即將結束時審判，以神聖震擊維持日光或在三點聖能時使用，驅邪術與十字軍聖擊。提醒與探索賽季懲戒內建循環相同。"
L["rm.tbc.paladin.holy.Name"] = "神聖（Icy Veins & Wowhead）"
L["rm.tbc.paladin.holy.Description"] = "神聖聖騎士在隊伍中的治療，作用於你的友方目標：目標瀕死時使用聖療術或神聖震擊，淨化術（42 級前為純淨術），移動時使用神聖震擊，承受大量傷害時使用聖光術，以等級 5 的聖光術維持光明賜福，否則使用聖光閃現。目標為敵對時維持智慧審判。提醒：專注光環、智慧祝福、神聖啟發與神恩術。單人練功的神聖聖騎士會改用懲戒內建循環。"
L["rm.tbc.paladin.holy.wowhead.Name"] = "神聖（Wowhead 坦克治療）"
L["rm.tbc.paladin.holy.wowhead.Description"] = "Wowhead 的團隊坦克治療，作為推薦的神聖內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。只要目標損失十分之一的生命力就使用聖光術，只在損失較少時使用聖光閃現；緊急處理、淨化、審判與提醒都與綜合版神聖內建循環相同。"
L["rm.tbc.paladin.protection.icyveins.Name"] = "防護（Icy Veins）"
L["rm.tbc.paladin.protection.icyveins.Description"] = "Icy Veins 的坦克循環，作為推薦的 Wowhead 防護內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。沒有人維持十字軍審判時施放它，正義聖印（怪群時用智慧聖印），奉獻作為主要威脅值來源，審判、神聖之盾，接著復仇之盾與憤怒之錘冷卻結束即使用。提醒與 Wowhead 版本相同，但不含復仇之怒。"
L["rm.tbc.paladin.protection.wowhead.Name"] = "防護（Wowhead & 模擬器）"
L["rm.tbc.paladin.protection.wowhead.Description"] = "防護天賦樹或任何開啟正義之怒的聖騎士的坦克循環。以神聖之盾、復仇之盾與審判拉怪；面對碾壓目標（世界首領或比你高三級以上）時先使用神聖之盾；接著是奉獻、對不死族與惡魔使用驅邪術、審判、神聖之盾、對不死族怪群使用神聖憤怒，除碾壓目標外使用復仇之盾。法力不足時對怪群使用智慧聖印，否則使用正義聖印。提醒：正義之怒、虔誠光環、庇護祝福（或王者祝福、智慧祝福）、復仇之怒、聖療術。嘲諷與切換目標由你自行處理。"
L["rm.tbc.paladin.retribution.icyveins.Name"] = "懲戒（Icy Veins）"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "Icy Veins 的懲戒，作為推薦的 Wowhead 懲戒內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。每個目標施放一次十字軍審判，正義聖印（只在使用慢速武器時用命令聖印，學會後改用血之聖印），十字軍聖擊、憤怒之錘與審判冷卻結束即使用，兩個以上敵人時使用奉獻，對不死族與惡魔使用驅邪術，神聖系升級者使用神聖震擊。提醒與 Wowhead 版本相同。"
L["rm.tbc.paladin.retribution.twist.Name"] = "懲戒聖印輪替"
L["rm.tbc.paladin.retribution.twist.Description"] = "預設關閉；如果你會輪替聖印（64 級以上，擁有命令聖印與血之聖印），請啟用它。以十字軍審判開場，之後每次揮擊都會提早施放命令聖印（等級 1），並在最後 0.4 秒切換為血之聖印，兩次輪替之間使用十字軍聖擊，只審判血之聖印，驅邪術與奉獻只作為填充，法力低於 12% 時不再輪替，只維持血之聖印。需要可靠的攻擊計時器；未將延遲納入考量。"
L["rm.tbc.paladin.retribution.wowhead.Name"] = "懲戒（Wowhead & 模擬器）"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "懲戒近戰，適用於 1 至 70 級，也是沒有其他內建循環適用時所有聖騎士的預設循環。對每個目標以智慧審判（法力低時）或十字軍審判開場，維持你最好的聖印（血之聖印、命令聖印，其次是正義聖印），使用十字軍聖擊，只審判正義聖印或血之聖印（對昏迷的目標則審判命令聖印），對不死族與惡魔使用驅邪術，三個以上敵人且法力充足時使用奉獻。憤怒之錘交由你決定（Wowhead 只對逃跑的目標使用）。提醒：聖潔光環、懲罰光環或虔誠光環、對自己施放祝福、戰鬥後治療、復仇之怒。聖印輪替是另一個內建循環。"
